#!/usr/bin/env python3
"""Small self-contained destination pages; images are HTML, never JS-rendered."""
import base64,hashlib,html,json,re,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'review-pages';OUT.mkdir(exist_ok=True)
esc=lambda x:html.escape(str(x or ''),quote=True)
def read(p):return json.loads(p.read_text())
def image(p):
 b=p.read_bytes();mime='image/webp' if b[:4]==b'RIFF' else 'image/png' if b.startswith(b'\x89PNG') else 'image/jpeg'
 return 'data:'+mime+';base64,'+base64.b64encode(b).decode()
places=[read(p) for p in sorted(ROOT.glob('places/*/research.json'))]
seed_path=ROOT/'reviews/consolidated.json'
seed=read(seed_path)['review'] if seed_path.exists() else {}
style='''*{box-sizing:border-box}body{margin:0;background:#f4f1eb;color:#26372f;font:16px/1.5 system-ui}header,main{max-width:1250px;margin:auto;padding:20px}nav{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}a{color:#285940}nav a,button{padding:8px 12px;border:1px solid #c4cec5;border-radius:8px;background:white;text-decoration:none;font:inherit}nav a[aria-current]{background:#285940;color:white}section,details.panel{background:white;border:1px solid #d7ddd7;border-radius:12px;padding:18px;margin:20px 0}h1{margin:8px 0}h2{font-size:23px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}img{display:block;width:100%;height:auto;max-height:540px;object-fit:contain;background:#eee;border-radius:6px}figcaption{font-size:14px;padding:9px 0}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:12px 0}textarea{width:100%;min-height:70px;padding:10px;font:inherit;border:1px solid #b6c4b9;border-radius:6px}small,.muted{color:#526456}.notice{padding:10px;background:#fff2d5;border-left:3px solid #c39343}summary{cursor:pointer;font-weight:650}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #ddd}.scroll{overflow:auto}button{cursor:pointer}@media(max-width:650px){.pair{grid-template-columns:1fr}header,main{padding:12px}}'''
script='''const seed=__SEED__;const storageKey='el-review-16-20261104';let review={...seed};try{Object.entries(JSON.parse(localStorage.getItem(storageKey)||'{}')).forEach(([k,v])=>{if(!review[k]||!review[k].at||v.at>review[k].at)review[k]=v})}catch(e){}try{if(location.hash.startsWith('#revision='))Object.assign(review,JSON.parse(decodeURIComponent(location.hash.slice(10))))}catch(e){}function capture(){document.querySelectorAll('[data-review-key]').forEach(section=>{const key=section.dataset.reviewKey,selected=section.querySelector('input[type=radio]:checked'),comment=section.querySelector('textarea').value;if(selected||comment)review[key]={...(review[key]||{}),...(selected?{status:selected.value}:{}),comment};});}function persist(){try{localStorage.setItem(storageKey,JSON.stringify(review));document.getElementById('save-state').textContent=Object.keys(review).length+' decisiones/comentarios guardados. Exporta antes de cerrar.'}catch(e){document.getElementById('save-state').textContent='No se pudo guardar localmente. Exporta tu revisión.'}}document.querySelectorAll('[data-review-key]').forEach(section=>{const key=section.dataset.reviewKey,v=review[key]||{};const note=section.querySelector('textarea');note.value=v.comment||'';section.querySelectorAll('input[type=radio]').forEach(input=>{input.checked=input.value===v.status;input.addEventListener('change',()=>{review[key]={...(review[key]||{}),status:input.value,at:new Date().toISOString()};persist()})});note.addEventListener('input',()=>{review[key]={...(review[key]||{}),comment:note.value};persist()})});document.getElementById('export').addEventListener('click',()=>{capture();persist();if(!Object.keys(review).length){alert('No hay decisiones ni comentarios para exportar. Marca una imagen o escribe un comentario.');return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({batch:'2026-11-04-16',exported_at:new Date().toISOString(),review},null,2)],{type:'application/json'}));a.download='revision-16-destinos.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});persist();document.getElementById('import').addEventListener('change',async event=>{try{const data=JSON.parse(await event.target.files[0].text());if(data.batch!=='2026-11-04-16'||!data.review)throw Error('Lote incorrecto');review={...review,...data.review};persist();location.reload()}catch(e){alert('No se pudo importar: '+e.message)}});'''
def geo(g):
 if not g or g.get('latitude') is None:return 'Coordenada precisa pendiente'
 return esc(f"{g['latitude']}, {g['longitude']}")
count=0
for idx,d in enumerate(places):
 slug=d['slug'];folder=ROOT/'places'/slug
 entries=[('hero','Portada')]+[(a.get('image_key',f'attraction-{i+1:02}'),a['name']) for i,a in enumerate(d['attractions'])]
 for e in d['experiences']:
  if e.get('image_key') and e['image_key'] not in [k for k,t in entries]:entries.append((e['image_key'],'Experiencia · '+e['name']))
 parts=[f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(d["name"])} · Revisión de 16 destinos</title><style>{style}</style></head><body><header><p>16 destinos · Comparativo de originales y propuestas</p><h1>{idx+1}. {esc(d["name"])}</h1><p>{esc(d["intro_draft_es"])}</p><nav>']
 for other in places:parts.append(f'<a href="{other["slug"]}.html"'+(' aria-current="page"' if other['slug']==slug else '')+'>'+esc(other['name'])+'</a>')
 parts+=['</nav><div class="controls"><button type="button" id="export">Exportar revisión</button><label>Importar <input id="import" type="file" accept="application/json"></label></div><p id="save-state" class="muted">Las imágenes no requieren JavaScript. Exporta tus decisiones antes de cambiar de destino. Las aprobaciones recibidas por chat ya están incorporadas.</p><noscript><p class="notice">Este visor no ejecuta JavaScript: puedes ver las imágenes, pero para guardar y exportar comentarios abre el archivo en un navegador completo.</p></noscript></header><main>']
 for key,title in entries:
  ref=read(folder/'references'/f'{key}.json');manifest=read(folder/'images'/f'{key}.manifest.json');original=folder/'references'/f'{key}.jpg';preview=folder/'references'/f'{key}-review-640.webp'
  if not preview.exists() or preview.stat().st_mtime<original.stat().st_mtime:
   subprocess.run(['cwebp','-quiet','-q','72','-resize','640','0',str(original),'-o',str(preview)],check=True)
  output=folder/'images'/f'{key}-1200.webp';digest=hashlib.sha256(output.read_bytes()).hexdigest();reviewkey=f'{slug}:{key}:{digest}'
  author=re.sub('<[^>]+>','',ref.get('author_html') or ref.get('author') or '')
  parts+=[f'<section data-review-key="{reviewkey}"><h2>{esc(title)}</h2><div class="pair"><figure><figcaption><strong>Original de referencia</strong></figcaption><img src="{image(preview)}" alt="Fotografía de referencia: {esc(title)}" decoding="async"><figcaption><a href="{esc(ref.get("source_url") or ref.get("source_page"))}" target="_blank" rel="noopener">Fuente</a> · {esc(author)}<br>{esc(ref.get("license"))}</figcaption></figure><figure><figcaption><strong>{"Fotografía licenciada conservada" if manifest.get("kind")=="licensed_photograph" else "Ilustración propuesta"}</strong></figcaption><img src="{image(folder/'images'/f'{key}-640.webp')}" alt="Propuesta: {esc(title)}" decoding="async"><figcaption>Vista previa WebP · Versión {digest[:10]}</figcaption></figure></div><div class="controls"><label><input type="radio" name="{key}" value="approved"> Aprobar</label><label><input type="radio" name="{key}" value="changes_requested"> Pedir ajuste</label><label><input type="radio" name="{key}" value="pending"> Pendiente</label></div><textarea aria-label="Comentario: {esc(title)}" placeholder="Escribe aquí qué conservar o corregir"></textarea></section>']
  count+=1
 parts.append('<details class="panel"><summary>Contenido, ubicación y experiencias</summary><h2>Por qué visitarlo</h2><ul>'+''.join('<li>'+esc(t)+'</li>' for t in d.get('why_visit_es',[]))+'</ul><p>Referencia del destino: '+geo(d.get('geolocation'))+'</p>')
 for a in d['attractions']:parts.append('<h3>'+esc(a['name'])+'</h3><p>'+esc(a.get('description_es'))+'</p><p>'+geo(a.get('geolocation'))+'</p>')
 for e in d['experiences']:parts.append('<h3>'+esc(e['name'])+'</h3><p>'+esc(e.get('description_es') or e.get('public_description_es') or e.get('notes'))+'</p><a href="'+esc(e.get('source_url') or e.get('offer_url'))+'">Consultar oferta documentada</a>')
 parts.append('</details><details class="panel"><summary>Negocios ('+str(len(d['businesses']))+' fichas)</summary><p>Fichas públicas candidatas; no implica verificación, alianza ni funcionamiento confirmado.</p><div class="scroll"><table><tr><th>Nombre</th><th>Categoría</th><th>Coordenadas</th><th>Fuente</th></tr>')
 for b in d['businesses']:parts.append('<tr><td>'+esc(b['name'])+'</td><td>'+esc(b.get('category'))+'</td><td>'+geo(b.get('geolocation'))+'</td><td><a href="'+esc(b.get('source_url'))+'">Fuente</a></td></tr>')
 parts.append('</table></div></details></main><script>'+script.replace('__SEED__',json.dumps(seed,ensure_ascii=False).replace('<','\\u003c'))+'</script></body></html>')
 page=''.join(parts);(OUT/f'{slug}.html').write_text(page)
 if idx==0:
  for other in places:page=page.replace(f'href="{other["slug"]}.html"',f'href="review-pages/{other["slug"]}.html"')
  (ROOT/'review.html').write_text(page)
print('Static review: 16 pages,',count,'pairs; all images present before JavaScript runs')
